// Checks every language file in lang/ against the English source list
// (lang/keys.json, generated by scripts/i18n-extract.mjs).
import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import { initI18n, t, tn } from './i18n.js';

const langDir = path.resolve(import.meta.dirname, '../../../lang');
const keys = JSON.parse(fs.readFileSync(path.join(langDir, 'keys.json'), 'utf8'));
const locales = fs
    .readdirSync(langDir)
    .filter((f) => /^[a-z]{2}\.json$/.test(f))
    .map((f) => f.replace('.json', ''));

const placeholders = (s) => [...String(s).matchAll(/\{([a-zA-Z0-9_]+)\}/g)].map((m) => m[1]).sort();

describe('translation files', () => {
    it('exist for every supported language except English', () => {
        expect(locales.length).toBeGreaterThanOrEqual(5);
    });

    for (const code of locales) {
        describe(code, () => {
            const dict = JSON.parse(fs.readFileSync(path.join(langDir, `${code}.json`), 'utf8'));

            it('translates every interface string', () => {
                const missing = keys.filter(({ key }) => dict[key] === undefined || dict[key] === '').map((k) => k.key);
                expect(missing).toEqual([]);
            });

            it('has no leftover keys that are no longer used', () => {
                const known = new Set(keys.map((k) => k.key));
                expect(Object.keys(dict).filter((k) => !known.has(k))).toEqual([]);
            });

            it('keeps every {placeholder} and gives plurals an "other" form', () => {
                const problems = [];
                for (const { key, one } of keys) {
                    const value = dict[key];
                    if (value === undefined) continue;
                    if (typeof value === 'object') {
                        if (!value.other) problems.push(`${key}: plural without "other"`);
                        for (const [form, text] of Object.entries(value)) {
                            // Singular forms may drop {count} ("one page"), all others must keep the same placeholders.
                            const expected = placeholders(form === 'one' && one ? one : key).filter((p) => form !== 'one' || p !== 'count' || text.includes('{count}'));
                            const got = placeholders(text).filter((p) => form !== 'one' || p !== 'count' || text.includes('{count}'));
                            if (JSON.stringify(expected) !== JSON.stringify(got)) problems.push(`${key} [${form}]: ${got} vs ${expected}`);
                        }
                    } else if (JSON.stringify(placeholders(key)) !== JSON.stringify(placeholders(value))) {
                        problems.push(`${key}: {${placeholders(value)}} vs {${placeholders(key)}}`);
                    }
                }
                expect(problems).toEqual([]);
            });

            it('works through t() and tn()', () => {
                initI18n({ locale: code, ui: dict });
                expect(t('Clear')).toBe(typeof dict.Clear === 'string' ? dict.Clear : 'Clear');
                const pages = tn('{count} page', '{count} pages', 5);
                expect(pages).toContain('5');
                expect(pages).not.toMatch(/\{count\}/);
                initI18n({ locale: 'en', ui: {} });
            });
        });
    }
});
